const onChoose = useCallback((chosenSide) => {
  if (!pair || pair.length !== 2) return;

  const now = performance.now();
  const elapsed = (now - startTimeRef.current)/1000;

  const left = pair[0];
  const right = pair[1];
  const chosen = chosenSide === "left" ? left : right;
  const notChosen = chosenSide === "right" ? left : right;

  setResults(r => [...r, { left: left.id, right: right.id, chosen: chosen.id, notChosen: notChosen.id, timestamp: Date.now(), elapsedTime: elapsed }]);
  setTimes(t => [...t, elapsed]); 
  setChosenVids(c => [...c, chosen.id]); 
  setNotChosenVids(n => [...n, notChosen.id]); 
  if (pool.length === 0) {
    setEnded(true);
    setPair([]);
    return;
  }
  console.log("we have ", (pairs).length, " left");

  const alpha = 0.5;

  setBetas(prev => {
    const beta_i = prev[chosen.id];
    const beta_j = prev[notChosen.id];

    const p = Math.exp(beta_i) / (Math.exp(beta_i) + Math.exp(beta_j));

    const new_i = beta_i + alpha * (1 - p);
    const new_j = beta_j - alpha * (1 - p);

    return {
      ...prev,
      [chosen.id]: new_i,
      [notChosen.id]: new_j
    };
  });

  const nextPair = pairs[1];
  if (!nextPair) {
    console.log("no next pair anymore");
    setEnded(true);
    setPair([]);
    return;
  }
  setVisible(false);
  setTimeout(() => {
    setCurrent({ chosen, notChosen, elapsed });
    startTimeRef.current = (performance.now());

    set_current_video_pair({
      chosen,
      notChosen,
      elapsed,
    });
    setPairs(p => p.slice(1)); // remove the current pair from the set of pairs to display
    setPair(nextPair); // set current pair to top pair
    setVidnum(v => v + 1); // increment pair number 
    console.log("pool is now: ");
    console.log(pool);
    console.log("pairs are now: ");
    console.log(pairs);
    setVisible(true);
  }, 500);
  setStart(performance.now());
}, [pair, pool, pairs]);

