function DemographicsForm({ errors, countries, professions }) {
    const [age, setAge] = useState("");
    const [highestDegree, setHighestDegree] = useState("");
    const [numLanguages, setNumLanguages] = useState("");
    const [interests, setinterests] = useState("");
    const [profession, setProfession] = useState("");
    const [customProfession, setCustomProfession] = useState("");
    const ages = ["Under 18 years", "18 - 22 years", "23 - 27 years", "28 - 32 years",  "33 - 37 years", "38 - 42 years", "43 - 50 years", "50+ years and over"];
    const degrees = ["High School Diploma", "Bachelor's", "Graduate/Master's", "Ph.D/Doctorate"];
    const languageNums = ["1", "2", "3", "4 or more"];   

    const handleinterestsChange = (e) => {
       setinterests(e.target.value);
       demographicsData["interests"] = e.target.value;
       console.log("New interests: "+demographicsData["interests"]);
    };

    const handleNumLanguagesChange = (e) => {
       setNumLanguages(e.target.value);
       demographicsData["numLanguages"] = e.target.value;
       console.log("number of languages: "+demographicsData["numLanguages"]);
    };


    const syncProfession = (list, custom) => {
       const typed = custom.trim();
       const combined = [...list, ...(typed ? [typed] : [])].join(",");
       demographicsData["profession"] = combined;
       console.log("New profession: " + combined);
    };

    // user picked from the list
    const handleProfessionChange = (selectedList) => {
       setProfession(selectedList);
       setCustomProfession(""); // search box clears after a selection
       syncProfession(selectedList, "");
    };

    // user typed in the search box
    const handleProfessionSearch = (value) => {
       const isCustom = value.trim() !== "" && !professions.includes(value);
       const custom = isCustom ? value : "";
       setCustomProfession(custom);
       syncProfession(profession, custom);
    };

    const commitCustomProfession = () => {
       const typed = customProfession.trim();
       setCustomProfession("");
       if (!typed || profession.includes(typed)) return;

       const updated = [...profession, typed];   // keep existing chips, add the typed one
       setProfession(updated);
       syncProfession(updated, "");
    };

    return (
       <Box sx={{display: 'flex', flexDirection: 'column', justifyContent: 'left', marginLeft: '5%', }}>
           <Box sx={{ display: 'flex', flexDirection: 'column', marginBottom: 2 }}>
               <Typography sx={{  }}> Please select which age range applies to you: </Typography>
                   <Select value={age} required onChange={(e) => {
                          setAge(e.target.value);
                          demographicsData["age"] = e.target.value; 
                          console.log("demographics data: ", demographicsData["age"]);
                       }} displayEmpty>
                       {ages.map((a) => (
                           <MenuItem key={a} value={a}>
                                {a}
                           </MenuItem>
                       ))}
                   </Select>
                   {errors.age && <Typography color="error" variant="caption">{errors.age}</Typography>}
           </Box>
           <Box sx={{ display: 'flex', flexDirection: 'column', marginBottom: 2 }}>
               <Typography sx={{  }}> Please select the highest certification you received: </Typography>
                   <Select value={highestDegree} required onChange={(e) => {
                          setHighestDegree(e.target.value);
                          demographicsData["highestDegree"] = e.target.value; 
                          console.log("demographics data: ", demographicsData["highestDegree"]);
                       }} displayEmpty>
                       {degrees.map((s) => (
                           <MenuItem  key={s} value={s}>
                                {s}
                           </MenuItem>
                       ))}
                   </Select>
                   {errors.highestDegree && <Typography color="error" variant="caption">{errors.highestDegree}</Typography>}
           </Box>
           <Box sx={{ display: 'flex', flexDirection: 'column', marginBottom: 2 }}>
               <Typography sx={{  }}> How many languages do you speak? </Typography>
                   <Select value={numLanguages} required onChange={(e) => {
                          setNumLanguages(e.target.value);
                          demographicsData["numLanguages"] = e.target.value; 
                          console.log("demographics data: ", demographicsData["numLanguages"]);
                       }} displayEmpty>
                       {languageNums.map((s) => (
                           <MenuItem  key={s} value={s}>
                                {s}
                           </MenuItem>
                       ))}
                   </Select>
                   {errors.numLanguages && <Typography color="error" variant="caption">{errors.numLanguages}</Typography>}
           </Box>
           <Box sx={{ display: 'flex', flexDirection: 'column', marginBottom: 2 }}>
               <Typography sx={{  }}> What are your interests? </Typography>
                   <Box sx={{borderRadius: 1, border: '1px solid', borderColor: 'divider'}}>

                   <TextField
                   sx={{ width: '100%', }}
                   onChange={handleinterestsChange} // Function will trigger on change event
                   displayValue="Enter interests" // Property name to display in the dropdown options
                   />                   
                   
                   </Box>
                   {errors.interests && <Typography color="error" variant="caption">{errors.interests}</Typography>}
           </Box>
       </Box>
    );
}

